## Why This Is Asked

This question validates core competencies in data modeling, local persistence, data aggregation, SwiftUI visualization, and crash-safe resume behavior, along with the candidate's ability to plan basic testing.

## Key Concepts

- Codable and FileManager for JSON persistence
- SwiftUI Canvas for custom chart rendering
- Date normalization to day granularity for aggregation
- Atomic file writes for crash safety
- Lightweight test planning

## Code Example

```swift
struct MoodEntry: Codable, Identifiable {
    let id: UUID
    let date: Date
    let mood: Int // 1-5 scale
    let note: String?
}
```

```swift
class MoodStore: ObservableObject {
    @Published var entries: [MoodEntry] = []

    private let url: URL
    private let fileManager = FileManager.default
    private let queue = DispatchQueue(label: "com.moodgraph.persistence")

    init() {
        let documentsURL = fileManager.urls(for: .documentDirectory, in: .userDomainMask)[0]
        self.url = documentsURL.appendingPathComponent("mood_entries.json")
        load()
    }

    func addEntry(mood: Int, note: String?) {
        let entry = MoodEntry(id: UUID(), date: Date(), mood: mood, note: note)
        entries.append(entry)
        save()
    }

    private func save() {
        queue.async { [weak self] in
            guard let self = self else { return }
            do {
                let data = try JSONEncoder().encode(self.entries)
                let tempURL = self.url.deletingLastPathComponent()
                    .appendingPathComponent("mood_entries_temp.json")
                try data.write(to: tempURL, options: .atomic)
                try fileManager.moveItem(at: tempURL, to: self.url)
            } catch {
                print("Failed to save: \(error)")
            }
        }
    }

    private func load() {
        guard fileManager.fileExists(atPath: url.path) else { return }
        do {
            let data = try Data(contentsOf: url)
            entries = try JSONDecoder().decode([MoodEntry].self, from: data)
        } catch {
            print("Failed to load: \(error)")
        }
    }

    func dailyAverages() -> [(date: Date, average: Double)] {
        let calendar = Calendar.current
        let grouped = Dictionary(grouping: entries) { entry in
            calendar.startOfDay(for: entry.date)
        }
        return grouped.map { (date, entries) in
            let avg = Double(entries.reduce(0) { $0 + $1.mood }) / Double(entries.count)
            return (date: date, average: avg)
        }.sorted { $0.date < $1.date }
    }
}
```

```swift
struct MoodChartView: View {
    let data: [(date: Date, average: Double)]

    var body: some View {
        Canvas { context, size in
            guard data.count > 1 else { return }
            let maxMood: Double = 5.0
            let stepX = size.width / CGFloat(data.count - 1)

            var path = Path()
            for (index, point) in data.enumerated() {
                let x = CGFloat(index) * stepX
                let y = size.height - (CGFloat(point.average / maxMood) * size.height)
                if index == 0 {
                    path.move(to: CGPoint(x: x, y: y))
                } else {
                    path.addLine(to: CGPoint(x: x, y: y))
                }
            }

            context.stroke(path, with: .color(.blue), lineWidth: 2)
        }
        .frame(height: 200)
    }
}
```

## Test Plan

1. **Unit Tests**
   - Verify MoodEntry encoding/decoding roundtrip
   - Test dailyAverages() with known input data
   - Validate mood range enforcement (1-5)

2. **Integration Tests**
   - Add entry, verify file exists in Documents
   - Restart app, verify entries persist
   - Add multiple entries same day, verify correct average

3. **UI Tests**
   - Verify mood picker limits selection to 1-5
   - Confirm note field is optional
   - Validate chart renders non-empty data

## Implementation
- PHPickerViewController (iOS 14+) via UIViewControllerRepresentable for SwiftUI video capture with 10s limit
- AVAssetImageGenerator extracts thumbnails from captured video
- FileManager.documentDirectory stores app-managed .mov and .png files
- SwiftUI LazyVGrid displays searchable grid with TextField search and DatePicker date filter
- @State manages Codable metadata JSON persistence
- All controls need .accessibilityLabel() for VoiceOver

## Key Code
```swift
struct VideoPicker: UIViewControllerRepresentable {
    @Binding var videoURL: URL?
    func makeUIViewController() -> PHPickerViewController {
        var config = PHPickerConfiguration()
        config.filter = .videos
        config.selectionLimit = 1
        let picker = PHPickerViewController(configuration: config)
        return picker
    }
}

struct CheckpointView: View {
    @State private var videos: [VideoMetadata] = []
    @State private var searchText = ""
    @State private var selectedDate = Date()

    var filteredVideos: [VideoMetadata] {
        videos.filter { video in
            video.title.localizedCaseInsensitiveContains(searchText) &&
            Calendar.current.isDate(video.date, inSameDayAs: selectedDate)
        }
    }

    var body: some View {
        LazyVGrid(columns: [GridItem(.adaptive(minimum: 100))]) {
            ForEach(filteredVideos) { video in
                VideoCell(video: video)
                    .accessibilityLabel("Video \(video.title)")
            }
        }
    }
}
```

